    "sentence_pattern": [{"value": "结论（「原话」）", "occurrences": [{"phase": 1, "quote": "该阶段原文摘录"}]}, {"value": "结论（「原话」）", "occurrences": [{"phase": 2, "quote": "该阶段原文摘录"}]}],
